import pandas as pd
import numpy as np
from collections import Counter
from itertools import combinations

# Parse data
df = pd.read_excel('/root/data.xlsx', sheet_name='Data')
data = df.iloc[7:].copy()
data.columns = ['A', 'B', 'turn_number', 'game_number', 'roll1', 'roll2', 'roll3', 'roll4', 'roll5', 'roll6'] + [f'extra_{i}' for i in range(11)]
data = data[['turn_number', 'game_number', 'roll1', 'roll2', 'roll3', 'roll4', 'roll5', 'roll6']].copy()
data = data.dropna(subset=['turn_number', 'game_number'])
for col in data.columns:
    data[col] = pd.to_numeric(data[col], errors='coerce')
data = data.dropna().astype(int)

# --- Scoring functions ---

def score_high_and_often(rolls):
    """Highest number * count of that number"""
    counts = Counter(rolls)
    highest = max(rolls)
    return highest * counts[highest]

def score_summation(rolls):
    """Sum of all six dice"""
    return sum(rolls)

def score_highs_and_lows(rolls):
    """Highest * lowest * (highest - lowest)"""
    hi = max(rolls)
    lo = min(rolls)
    return hi * lo * (hi - lo)

def check_only_two_numbers(rolls):
    """All six rolls are one of exactly two numbers"""
    return len(set(rolls)) == 2

def check_all_the_numbers(rolls):
    """Rolls are 1-2-3-4-5-6 in any order"""
    return set(rolls) == {1, 2, 3, 4, 5, 6}

def check_ordered_subset_of_four(rolls):
    """Contains a run of 4 consecutive increasing or decreasing numbers in order rolled"""
    n = len(rolls)
    for i in range(n - 3):
        # Check increasing
        if all(rolls[j+1] == rolls[j] + 1 for j in range(i, i+3)):
            return True
        # Check decreasing
        if all(rolls[j+1] == rolls[j] - 1 for j in range(i, i+3)):
            return True
    return False

def get_possible_scores(rolls):
    """Return a dict of category -> score for all applicable categories"""
    scores = {}
    scores['high_and_often'] = score_high_and_often(rolls)
    scores['summation'] = score_summation(rolls)
    scores['highs_and_lows'] = score_highs_and_lows(rolls)
    if check_only_two_numbers(rolls):
        scores['only_two_numbers'] = 30
    if check_all_the_numbers(rolls):
        scores['all_the_numbers'] = 40
    if check_ordered_subset_of_four(rolls):
        scores['ordered_subset_of_four'] = 50
    return scores

def best_game_score(turn1_scores, turn2_scores):
    """Find the highest combined score using each category at most once"""
    categories = set(turn1_scores.keys()) | set(turn2_scores.keys())

    best = 0
    # Try all possible assignments:
    # For each category used by turn1, it can't be used by turn2
    # We want to maximize turn1_score + turn2_score

    # Get list of categories available for each turn
    t1_cats = list(turn1_scores.keys())
    t2_cats = list(turn2_scores.keys())

    # Try every combination: pick one category for turn1, one different category for turn2
    for c1 in t1_cats:
        for c2 in t2_cats:
            if c1 != c2:
                total = turn1_scores[c1] + turn2_scores[c2]
                if total > best:
                    best = total

    # Also consider using only one turn (assign category to only one turn)
    for c1 in t1_cats:
        if turn1_scores[c1] > best:
            best = turn1_scores[c1]
    for c2 in t2_cats:
        if turn2_scores[c2] > best:
            best = turn2_scores[c2]

    return best

# --- Process all games ---

# Group by game number
games = {}
for _, row in data.iterrows():
    gn = row['game_number']
    rolls = [row['roll1'], row['roll2'], row['roll3'], row['roll4'], row['roll5'], row['roll6']]
    if gn not in games:
        games[gn] = []
    games[gn].append(rolls)

# Calculate game scores
game_scores = {}
for gn in sorted(games.keys()):
    turns = games[gn]
    if len(turns) == 2:
        t1_scores = get_possible_scores(turns[0])
        t2_scores = get_possible_scores(turns[1])
        game_scores[gn] = best_game_score(t1_scores, t2_scores)
    elif len(turns) == 1:
        t1_scores = get_possible_scores(turns[0])
        game_scores[gn] = max(t1_scores.values())
    else:
        print(f"Warning: game {gn} has {len(turns)} turns")

print(f"Total games scored: {len(game_scores)}")
print(f"Game number range: {min(game_scores.keys())} to {max(game_scores.keys())}")

# Now match odd vs even games
# Player 1 plays odd games (1, 3, 5, ...), Player 2 plays even games (2, 4, 6, ...)
# Matches: game 1 vs game 2, game 3 vs game 4, etc.

player1_wins = 0
player2_wins = 0
draws = 0

for i in range(1, max(game_scores.keys()), 2):
    odd_game = i      # Player 1's game
    even_game = i + 1  # Player 2's game

    if odd_game in game_scores and even_game in game_scores:
        p1_score = game_scores[odd_game]
        p2_score = game_scores[even_game]

        if p1_score > p2_score:
            player1_wins += 1
        elif p2_score > p1_score:
            player2_wins += 1
        else:
            draws += 1

print(f"\nPlayer 1 wins: {player1_wins}")
print(f"Player 2 wins: {player2_wins}")
print(f"Draws: {draws}")
print(f"Answer (P1 wins - P2 wins): {player1_wins - player2_wins}")

# Verify some individual game scores
print("\n--- Verification ---")
for gn in [1, 2, 3, 4, 5]:
    turns = games[gn]
    print(f"\nGame {gn}:")
    for i, t in enumerate(turns):
        scores = get_possible_scores(t)
        print(f"  Turn {i+1}: rolls={t}, scores={scores}")
    print(f"  Game score: {game_scores[gn]}")

